const ROTA_API = 'https://script.google.com/macros/s/AKfycbw1IBSKWEB4Hn3k-MGidvGRkVwQS9YyUts4vKxGucFojYH5KWjm32FXbnfXLit-NRxk-g/exec';
const ACCT_RX = /^[A-Z]{2,4}\/\d{2}-\d{2}\/\d{1,5}$/;
function acctNorm(x) { x = String(x || '').trim().toUpperCase().replace(/\s+/g, ''); const m = x.match(/^([A-Z]{2,4})\/?(\d{2})-?(\d{2})\/?(\d{1,5})$/); return m ? m[1] + '/' + m[2] + '-' + m[3] + '/' + m[4].padStart(4, '0') : x; }
async function rotaCall(action, data) {
  if (!S.token) throw new Error('Open the Nutvique app (installed app or vermakshat.com/nutvique) to see accounting vouchers.');
  const r = await fetch(ROTA_API, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify({ token: S.token, action: action, data: data || {} }) }).then(x => x.json()).catch(() => null);
  if (!r) throw new Error('Could not reach the Staff Rota app – check the internet and try again.');
  if (!r.ok) throw new Error(r.e || 'Staff Rota app error');
  return r.r;
}
async function acctView(no) {
