    '<div style="text-align:center;font-weight:800;color:#1F2A44">' + esc(c.name || 'NUTZY FOODS PRIVATE LIMITED') + '</div><div style="text-align:center;font-size:11px;color:#555">' + esc(c.addr || '') + (c.gstin ? '<br>GSTIN ' + esc(c.gstin) : '') + '</div>' +
    '<div style="text-align:center;font-weight:700;letter-spacing:.12em;border:1px solid #1F2A44;margin:8px 0;padding:3px;font-size:13px">CASH PAYMENT VOUCHER</div><div style="text-align:center;font-size:12px;margin-bottom:6px">' + esc(ex ? v.head : 'Travelling / local conveyance') + '</div>' +
    '<table class="t"><tr><td>Voucher no.</td><td><b>' + esc(v.no) + '</b></td></tr><tr><td>Status</td><td><b>' + esc(v.status) + '</b>' + (v.paidOn ? ' · paid ' + esc(pvD(v.paidOn)) + ' by ' + esc(v.paidBy) : '') + (v.payMode ? '<div class="tiny mute">' + esc(v.payMode) + '</div>' : '') + '</td></tr>' +
    '<tr><td>Debit</td><td>' + esc(v.head) + ' A/c</td></tr><tr><td>Paid to</td><td><b>' + esc(v.name) + '</b>' + (v.empId ? ' (' + esc(v.empId) + ')' : '') + (v.desig ? ' · ' + esc(v.desig) : '') + '</td></tr>' +
