  if (acct) { const p = await rotaCall('voucherStorePay', { no: acct.no, pv: r.voucher.no, store: loc, paidOn: r.voucher.date, amount: r.voucher.amount }).catch(e => { toast('Saved, but ' + acct.no + ' could not be marked paid in the Staff Rota app: ' + e.message, true); return null; }); if (p) toast(acct.no + ' marked paid from ' + pvLoc(loc)); }

$('#pv_pr', m) && ($('#pv_pr', m).onclick = () => pvPrint(v));
if ($('#pv_av', m)) $('#pv_av', m).onclick = () => acctView(v.acct);
if ($('#pv_al', m)) $('#pv_al', m).onclick = async () => {
  const no = acctNorm(prompt('Accounting voucher no. from the Staff Rota app (travel TV/…, expenses EV/…) for ' + v.no + ' (₹' + money(v.amount) + ' to ' + v.to + '):', v.acct || '') || ''); if (!no) return;
  if (!ACCT_RX.test(no)) { toast('Type the number like TV/26-27/0002', true); return; }
